pub fn get_item_type<M: ?Sized + 'static>(key: &str) -> JRef<M> {
    // Cast instead of using ItemType#typed, since item type can be a mock during testing and would return null
    let item_type = registry::ITEM.get_or_throw(akey::key_2(akey::MINECRAFT_NAMESPACE, key));
    cast::<M, _>(&item_type).unwrap_or_else(|| panic!("ClassCastException: item type {} is not a {}", key, std::any::type_name::<M>()))
} // paper-api/src/main/java/org/bukkit/inventory/ItemType.java:3415
